edits.new:
log_format benchmark '$remote_addr - $remote_user [$time_local] "$request" '
                    '$request_method $status $body_bytes_sent '
                    '"$http_referer" "$http_user_agent"';

access_log /var/log/nginx/access.log;

##
# Rate Limiting
##

limit_req_zone $binary_remote_addr zone=benchmark_limit:10m rate=10r/s;

input.command:
python3 - <<'EOF'
p='/etc/nginx/nginx.conf'
s=open(p).read()
add = '''	log_format benchmark '$remote_addr - $remote_user [$time_local] "$request" '
	                    '$request_method $status $body_bytes_sent '
	                    '"$http_referer" "$http_user_agent"';

	access_log /var/log/nginx/access.log;

	##
	# Rate Limiting
	##

	limit_req_zone $binary_remote_addr zone=benchmark_limit:10m rate=10r/s;'''
s=s.replace('\taccess_log /var/log/nginx/access.log;', add, 1)
open(p,'w').write(s)
EOF
mkdir -p /var/www/html /var/log/nginx
echo "Welcome to the benchmark webserver" > /var/www/html/index.html
echo "Page not found - Please check your URL" > /var/www/html/404.html
cat > /etc/nginx/conf.d/benchmark-site.conf <<'EOF'
server {
    listen 8080;
    listen [::]:8080;
    server_name localhost;

    root /var/www/html;
    index index.html;

    access_log /var/log/nginx/benchmark-access.log benchmark;
    error_log  /var/log/nginx/benchmark-error.log;

    limit_req zone=benchmark_limit burst=10 nodelay;

    location / {
        try_files $uri $uri/ =404;
    }

    error_page 404 /404.html;
    location = /404.html {
        root /var/www/html;
        internal;
    }
}
EOF
rm -f /etc/nginx/sites-enabled/default
nginx -t 2>&1
(service nginx restart || nginx) 2>&1 | tail -3
sleep 1
curl -s -i http://localhost:8080/ | head -5; echo "---"; curl -s http://localhost:8080/nope; echo "---"
echo "Access log location: /var/log/nginx/benchmark-access.log"
cat /var/log/nginx/benchmark-access.log
